alter table public.purchase_orders add column if not exists receive_location_id uuid references public.inventory_locations(id) on delete set null;
create table if not exists public.inventory_transactions(id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.inventory_items(id),location_id uuid references public.inventory_locations(id) on delete set null,job_id uuid references public.jobs(id) on delete set null,purchase_order_id uuid references public.purchase_orders(id) on delete set null,transaction_type text not null check(transaction_type in ('receive','job_use','adjustment')),quantity numeric not null,unit_cost numeric not null default 0,actor_user_id uuid references public.users(id),created_at timestamptz not null default now());alter table public.inventory_transactions enable row level security;create policy "staff read inventory transactions" on public.inventory_transactions for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch','technician'));
create or replace function public.receive_purchase_order_line(p_line_id uuid,p_quantity numeric,p_location_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_line public.purchase_order_items%rowtype;v_po public.purchase_orders%rowtype;v_tx uuid;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;if p_quantity<=0 then raise exception 'quantity must be positive';end if;select * into v_line from public.purchase_order_items where id=p_line_id for update;if v_line.id is null or v_line.inventory_item_id is null then raise exception 'invalid PO line';end if;if v_line.received_quantity+p_quantity>v_line.quantity then raise exception 'cannot receive more than ordered';end if;select * into v_po from public.purchase_orders where id=v_line.purchase_order_id for update;update public.purchase_order_items set received_quantity=received_quantity+p_quantity where id=v_line.id;update public.inventory_items set on_hand=on_hand+p_quantity,unit_cost=v_line.unit_cost,location_id=p_location_id where id=v_line.inventory_item_id;insert into public.inventory_transactions(inventory_item_id,location_id,purchase_order_id,transaction_type,quantity,unit_cost,actor_user_id) values(v_line.inventory_item_id,p_location_id,v_po.id,'receive',p_quantity,v_line.unit_cost,v_user.id) returning id into v_tx;update public.purchase_orders p set status=case when not exists(select 1 from public.purchase_order_items li where li.purchase_order_id=p.id and li.received_quantity<li.quantity) then 'received' else 'partial' end,received_at=case when not exists(select 1 from public.purchase_order_items li where li.purchase_order_id=p.id and li.received_quantity<li.quantity) then now() else p.received_at end where p.id=v_po.id;return v_tx;end$$;
create or replace function public.consume_inventory_for_job(p_job_id uuid,p_inventory_item_id uuid,p_quantity numeric) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_item public.inventory_items%rowtype;v_job public.jobs%rowtype;v_tx uuid;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','technician') then raise exception 'not authorized';end if;if p_quantity<=0 then raise exception 'quantity must be positive';end if;select * into v_job from public.jobs where id=p_job_id;if v_job.id is null or (v_user.role='technician' and v_job.technician_id<>v_user.id) then raise exception 'job access denied';end if;select * into v_item from public.inventory_items where id=p_inventory_item_id for update;if v_item.id is null or v_item.on_hand<p_quantity then raise exception 'insufficient inventory';end if;update public.inventory_items set on_hand=on_hand-p_quantity where id=v_item.id;insert into public.material_usage(job_id,inventory_item_id,sku,description,quantity,unit_cost,source) values(p_job_id,v_item.id,v_item.sku,v_item.description,p_quantity,v_item.unit_cost,'inventory');insert into public.inventory_transactions(inventory_item_id,location_id,job_id,transaction_type,quantity,unit_cost,actor_user_id) values(v_item.id,v_item.location_id,p_job_id,'job_use',-p_quantity,v_item.unit_cost,v_user.id) returning id into v_tx;update public.jobs set material_cost=coalesce((select sum(quantity*unit_cost) from public.material_usage where job_id=p_job_id),0) where id=p_job_id;return v_tx;end$$;revoke all on function public.receive_purchase_order_line(uuid,numeric,uuid) from public,anon;grant execute on function public.receive_purchase_order_line(uuid,numeric,uuid) to authenticated;revoke all on function public.consume_inventory_for_job(uuid,uuid,numeric) from public,anon;grant execute on function public.consume_inventory_for_job(uuid,uuid,numeric) to authenticated;
